using System;
using System.IO;
using UnityEngine;
namespace Rekindle {
 public sealed class Session:MonoBehaviour {
  [SerializeField]Character player;[SerializeField]OrbitCamera orbit;[SerializeField]ItemDefinition[] items;[SerializeField]AbilityDefinition blade,cleave,improvedBlade;[SerializeField]WorldInteractable[] interactables;[SerializeField]EnemyBrain[] enemies;[SerializeField]SoulPresentation[] souls;[SerializeField]WorldPhasePresentation phase;
  public WorldState World{get;private set;}public Inventory Bag{get;private set;}public Equipment Equipment{get;private set;}public Character Player=>player;public PlayerMotor Motor{get;private set;}public Combatant Combat{get;private set;}public PlayerInputSource Input{get;private set;}public OrbitCamera Orbit=>orbit;public bool Menu{get;private set;}=true;public bool Paused{get;private set;}public bool InventoryOpen{get;private set;}public WorldInteractable Inspected{get;private set;}public WorldInteractable Nearest{get;private set;}public string Message{get;private set;}public float MessageUntil{get;private set;}public SaveStore Saves{get;private set;}
  public void Configure(Character p,OrbitCamera o,ItemDefinition[] defs,AbilityDefinition a,AbilityDefinition b,AbilityDefinition upgrade,WorldInteractable[] interactions,EnemyBrain[] brains,SoulPresentation[] people,WorldPhasePresentation ph){player=p;orbit=o;items=defs;blade=a;cleave=b;improvedBlade=upgrade;interactables=interactions;enemies=brains;souls=people;phase=ph;}
  void Awake(){World=new WorldState();Bag=new Inventory();Equipment=new Equipment();Motor=player.GetComponent<PlayerMotor>();Combat=player.GetComponent<Combatant>();Input=player.GetComponent<PlayerInputSource>();Saves=new SaveStore(System.IO.Path.Combine(Application.persistentDataPath,"rekindle-v1.json"));foreach(var i in interactables)i.Bind(this);foreach(var e in enemies)e.Bind(this,player);foreach(var s in souls)s.Bind(this);phase.Bind(this);World.Changed+=WorldChanged;player.Died+=PlayerDied;orbit.RightClicked+=Click;SetBlocked();}
  void OnDestroy(){Time.timeScale=1;if(World!=null)World.Changed-=WorldChanged;if(player)player.Died-=PlayerDied;if(orbit)orbit.RightClicked-=Click;}
  void WorldChanged(){Equipment.Derive(World);Combat.Configure(Equipment.Improved?improvedBlade:blade,cleave);}
  public string ItemTitle(string id){foreach(var i in items)if(i.stableId==id)return i.title;return id;}
  public ItemDefinition Item(string id){foreach(var i in items)if(i.stableId==id)return i;return null;}
  public void Begin(bool load){if(load){var s=Saves.Read(data=>{var testWorld=new WorldState();return testWorld.Load(data,new Inventory());});if(s==null){Notify("No valid save found. Starting a new journey.");}else{World.Load(s,Bag);Motor.Teleport(new Vector3(s.x,Mathf.Max(1,s.y),s.z));player.Health.Restore(s.health);if(!player.Alive)player.Revive();foreach(var enemy in enemies)if(World.IsDefeated(enemy.GetComponent<Character>().Id))enemy.gameObject.SetActive(false);}}Menu=false;Paused=false;SetBlocked();Notify("Cinderhollow : Speak with the golden wisp. Hold LMB to look; W to walk; F to interact.",10);}
  public void Notify(string m,float duration=4){Message=m;MessageUntil=Time.unscaledTime+duration;}
  public void Inspect(WorldInteractable b){Inspected=b;SetBlocked();}
  public void ClosePanel(){Inspected=null;InventoryOpen=false;SetBlocked();}
  public void ToggleBag(){InventoryOpen=!InventoryOpen;Inspected=null;SetBlocked();}
  public void TogglePause(){if(Menu)return;Paused=!Paused;Inspected=null;InventoryOpen=false;SetBlocked();}
  void SetBlocked(){bool blocked=Menu||Paused||InventoryOpen||Inspected;Motor.Blocked=blocked;orbit.Blocked=blocked;Time.timeScale=Menu||Paused?0:1;Cursor.visible=true;Cursor.lockState=CursorLockMode.None;}
  public void Save(){if(Menu)return;try{var s=World.Snapshot(Bag);var p=player.transform.position;s.x=p.x;s.y=p.y;s.z=p.z;s.health=player.Health.Value;Saves.Write(s);}catch(Exception e){Notify("Could not save: "+e.Message);Debug.LogException(e);}}
  void OnApplicationQuit(){Save();}void OnApplicationPause(bool paused){if(paused)Save();}
  public void RestoreBuilding(){if(!Inspected)return;var b=Inspected;string reason=World.Block(b.Id);if(reason!=""){Notify(reason);return;}if(!World.Restore(b.Id,Bag)){Notify("More materials needed");return;}Feedback.Burst(b.transform.position+Vector3.up*2,new Color(1,.7f,.2f),60);Feedback.Tone(520,.4f);Notify(World.Complete?"DAWN RETURNS : Cinderhollow is alive because of you.":b.Title+" : "+(World.Stage(b.Id)==2?"restored":"stabilized"),8);if(b.Id=="forge"&&World.Stage("forge")==2)Notify("Mira restored : Dawn Blade equipped. Your basic attack is stronger.",7);Save();}
  public void UseBuildingService(){if(!Inspected||World.Stage(Inspected.Id)<2||Vector3.Distance(Inspected.transform.position,player.transform.position)>5)return;switch(Inspected.Id){case "hearth":player.Health.Restore(player.Health.Max);player.Energy.Restore(100);Notify("Elian welcomes you. Health and energy restored.");break;case "garden":if(World.IsDepleted("garden-harvest")){Notify("The first harvest has already been gathered.");return;}if(Bag.Add("food",6)){World.Deplete("garden-harvest");Notify("Sera shares the first harvest | +6 Wildfruit");}break;case "forge":player.Energy.Restore(100);Notify("Mira tends your Dawn Blade. Energy restored.");break;default:Notify("The Dawn Beacon shines over a valley you restored.",7);break;}Save();}
  public void EnemyDefeated(Character c){World.Defeat(c.Id);Bag.Add("food",1);if(c.Id=="warden"){Bag.Add("hammer",1);Bag.Add("ember",1);Notify("ASH WARDEN DEFEATED : Mira's hammer and the Dawn Ember recovered. Corruption recedes; use the waystone to return.",12);}else Notify("Ashbound released : +1 Wildfruit");Save();}
  void PlayerDied(){Combat.Stop();Notify("Your ember endures. Returning to the hearth:",6);Invoke(nameof(Recover),3);}
  void Recover(){Motor.Teleport(new Vector3(0,2,-8));player.Revive();Save();}
  public void UseFood(){if(player.Alive&&player.Health.Value<player.Health.Max&&Bag.Consume(new Stack("food",1))){player.Health.Add(45);Feedback.Burst(player.transform.position+Vector3.up,Color.green,10);Notify("Wildfruit : Restored 45 health");Save();}else Notify("You need wildfruit and missing health");}
  public void Action(int slot){if(Menu||Paused||InventoryOpen||Inspected||!player.Alive)return;switch(slot){case 0:Combat.TryAttack(false);break;case 1:if(!Combat.TryAttack(true))Notify("Ember Cleave needs 30 energy and an opening");break;case 2:Motor.Evade(player.transform.forward);break;case 3:UseFood();break;case 4:ToggleBag();break;case 5:if(World.Stage("hearth")==2&&Vector3.Distance(player.transform.position,Vector3.zero)<22){player.Health.Restore(player.Health.Max);Notify("The hearth restores you");}else Notify("Restore the Hearth House and rest near the settlement hearth");break;}}
  void Update(){if(Input.Pause.WasPressedThisFrame()){if(Inspected||InventoryOpen)ClosePanel();else TogglePause();}if(Menu||Paused)return;if(Input.Bag.WasPressedThisFrame())ToggleBag();if(InventoryOpen||Inspected)return;for(int n=0;n<6;n++)if(Input.Actions[n].WasPressedThisFrame())Action(n);if(Input.Target.WasPressedThisFrame())CycleTarget();Nearest=null;float nearest=5;foreach(var i in interactables){if(!i||!i.gameObject.activeInHierarchy)continue;float d=Vector3.Distance(player.transform.position,i.transform.position);if(d<nearest){nearest=d;Nearest=i;}}if(Input.Interact.WasPressedThisFrame()&&Nearest)Nearest.Interact();}
  void CycleTarget(){Character first=null,next=null;bool after=Combat.Target==null;foreach(var e in enemies){var c=e.GetComponent<Character>();if(!c.Alive||!e.gameObject.activeInHierarchy||Vector3.Distance(c.transform.position,player.transform.position)>24)continue;if(first==null)first=c;if(after&&next==null)next=c;if(c==Combat.Target)after=true;}Combat.Select(next?next:first);}
  void Click(Vector2 screen){if(Menu||Paused||Inspected||InventoryOpen)return;if(Physics.Raycast(Camera.main.ScreenPointToRay(screen),out var hit,150)){var c=hit.collider.GetComponentInParent<Character>();if(c&&c.Allegiance==Allegiance.Hostile){Combat.Select(c,true);Notify("Target: "+c.Title+" : Move within weapon reach");return;}var i=hit.collider.GetComponentInParent<WorldInteractable>();if(i)i.Interact();}}
 }
}
